function normTR(s) {
  return (s || "")
    .toLocaleLowerCase("tr-TR")
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/ı/g, "i").replace(/ş/g, "s").replace(/ğ/g, "g")
    .replace(/ü/g, "u").replace(/ö/g, "o").replace(/ç/g, "c")
    .replace(/\?/g, "").replace(/\s+/g, " ").trim();
}
function scoreMatch(item, q) {
  const title = normTR(item.title);
  const cat = normTR(item.cat);
  if (!q) return 0;
  if (title === q) return 1000;
  if (title.replace(/\s+/g, "") === q.replace(/\s+/g, "")) return 950;
  if (title.startsWith(q)) return 850;
  if (title.includes(q)) return 750;
  const qWords = q.split(" ").filter(Boolean);
  let score = 0;
  qWords.forEach(w => {
    if (title.includes(w)) score += 40;
    if (cat.includes(w)) score += 10;
  });
  return score;
}
function findMatches(query) {
  const q = normTR(query);
  if (!q) return [];
  return questions
    .map(item => ({ ...item, _score: scoreMatch(item, q) }))
    .filter(item => item._score > 0)
    .sort((a, b) => b._score - a._score || a.title.length - b.title.length)
    .slice(0, 14);
}
function renderResults(query) {
  if (!input || !results) return [];
  const found = findMatches(query);
  results.innerHTML = "";
  if (!normTR(query)) return [];
  results.innerHTML = found.length
    ? found.map((item,idx) => `<a class="result-item ${idx===0?'best-result':''}" href="${item.url}">${idx===0?'<em>En iyi eşleşme</em>':''}<strong>${item.title}</strong><small>${item.cat}</small></a>`).join("")
    : `<div class="result-item"><strong>Bu soru henüz ekli değil.</strong><small>Yeni içerik planına alınabilir.</small></div>`;
  return found;
}
function goBestMatch() {
  if (!input) return;
  const found = renderResults(input.value);
  if (found.length) window.location.href = found[0].url;
}
function shuffleExamples() {
  const buttons = Array.from(document.querySelectorAll("[data-fill]"));
  if (!buttons.length) return;
  const pool = [...examplePool].sort(() => Math.random() - .5);
  buttons.forEach((b, i) => {
    const val = pool[i % pool.length];
    b.dataset.fill = val;
    b.textContent = val.replace(" ne zaman", "").replace("?", "").slice(0, 28);
  });
}
if (form) form.addEventListener("submit", e => { e.preventDefault(); goBestMatch(); });
if (input) {
  input.addEventListener("input", () => renderResults(input.value));
  input.addEventListener("keydown", e => {
    if (e.key === "Enter") { e.preventDefault(); goBestMatch(); }
  });
}
document.addEventListener("DOMContentLoaded", () => {
  shuffleExamples();
  document.querySelectorAll("[data-fill]").forEach(b => b.addEventListener("click", () => {
    input.value = b.dataset.fill;
    renderResults(input.value);
    input.focus();
  }));
});

function mobileSearchActive(on){
  const card=document.querySelector('.search-card');
  if(!card)return;
  card.classList.toggle('search-active', !!on);
}
if(input){
  input.addEventListener('focus',()=>mobileSearchActive(true));
  input.addEventListener('blur',()=>setTimeout(()=>mobileSearchActive(false),250));
}
